INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (1, 57, 10077, "2021/10/18 12:00:00", -416.5, 0.0, 190802, 5, 10077005, "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", "カリン", "2021/10/27 14:59:59", 0.0, 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (1, 55, 10077, "2021/10/18 12:00:00", -363.0, 5.506, 190802, 1, 10077006, "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ", "カリン", "2021/10/27 14:59:59", 0.0, 2);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (2, 55, 10077, "2021/10/18 12:00:00", -363.0, 1.216, 190802, 2, 10077007, "お疲れ様です！\nここでは、討伐証と報酬を\n交換することができます！", "カリン", "2021/10/27 14:59:59", 0.0, 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (2, 56, 10077, "2021/10/18 12:00:00", -363.0, 1.539, 190802, 3, 10077008, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", "カリン", "2021/10/27 14:59:59", 0.0, 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (2, 56, 10077, "2021/10/18 12:00:00", -363.0, 1.875, 190802, 4, 10077009, "終わっちゃいましたねー\n討伐証は努力の証！\n報酬と交換しましょう！", "カリン", "2021/10/27 14:59:59", 0.0, 1);
