INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (1, 53, 20026, "2022/04/18 15:00:00", -416.5, 3.099, 190801, 2, 20026002, "ミッションをクリアして、\n報酬をゲットしましょう！", "カリン", "2030/01/01 14:59:59", 0.0, 2);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (1, 54, 20026, "2022/04/18 15:00:00", -416.5, 2.801, 190801, 3, 20026003, "受け取ることができる\n報酬があるようです\n確認してみてください", "カリン", "2030/01/01 14:59:59", 0.0, 2);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (2, 54, 20026, "2022/04/18 15:00:00", -416.5, 0.0, 190801, 4, 20026004, "報酬がもらえますよ！\nチェックしてみてください", "カリン", "2030/01/01 14:59:59", 0.0, 2);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (1, 57, 20026, "2022/04/18 15:00:00", -416.5, 0.0, 190801, 5, 20026005, "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", "カリン", "2030/01/01 14:59:59", 0.0, 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (1, 55, 20026, "2022/04/18 15:00:00", -363.0, 5.506, 190801, 1, 20026006, "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ", "カリン", "2030/01/01 14:59:59", 0.0, 2);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (2, 55, 20026, "2022/04/18 15:00:00", -363.0, 1.216, 190801, 2, 20026007, "お疲れ様です！\nここでは、討伐証と報酬を\n交換することができます！", "カリン", "2030/01/01 14:59:59", 0.0, 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (2, 56, 20026, "2022/04/18 15:00:00", -363.0, 1.539, 190801, 3, 20026008, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", "カリン", "2030/01/01 14:59:59", 0.0, 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (2, 56, 20026, "2022/04/18 15:00:00", -363.0, 1.875, 190801, 4, 20026009, "終わっちゃいましたねー\n討伐証は努力の証！\n報酬と交換しましょう！", "カリン", "2030/01/01 14:59:59", 0.0, 1);
