INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (2, 56, 20060, "2025/01/16 15:00:00", -363.0, 1.539, 190801, 3, 20060008, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", "カリン", "2030/01/01 14:59:59", 0.0, 1);
